using System.Runtime.CompilerServices;using DeskCanvas.Core;
internal static class SystemMonitorLayoutMath{internal static double NaturalHeight(double v)=>Math.Max(96,Math.Ceiling(double.IsFinite(v)?v:96));internal static bool KeepTop(CanvasItem i,double v){var n=NaturalHeight(v);if(Math.Abs(i.Height-n)<.5)return false;var top=i.CenterY-i.Height/2;i.Height=n;i.CenterY=top+n/2;return true;}internal static bool DividerVisible(bool a,bool b)=>a&&b;internal static(double Padding,double Header,double Row,bool Dense)Values(double width,double height,int rows,bool divider){width=Math.Max(96,width);height=Math.Max(96,height);var pad=Math.Clamp(Math.Min(width,height)*.052,5,12);var header=Math.Clamp(height*.105,12,24);var dividerSpace=divider?Math.Clamp(height*.075,5,14):0;return(pad,header,Math.Max(14,(height-header-dividerSpace)/Math.Max(1,rows)),width<280||height<260);}}
internal static class V30SystemLayerContractTests{[ModuleInitializer]internal static void Run(){Console.WriteLine("v30 layer: normalize");var low=new CanvasItem{ZIndex=int.MinValue};var tie=new CanvasItem{ZIndex=int.MinValue};var high=new CanvasItem{ZIndex=int.MaxValue};IList<CanvasItem> x=new List<CanvasItem>{high,low,tie};LayerOrderMath.NormalizeInto(x);Check(ReferenceEquals(x[0],low)&&ReferenceEquals(x[1],tie)&&ReferenceEquals(x[2],high));Console.WriteLine("v30 layer: moves");Check(LayerOrderMath.MoveUp(x,low));Check(LayerOrderMath.MoveToFront(x,low));Check(LayerOrderMath.MoveDown(x,low));Check(LayerOrderMath.MoveToBack(x,low));Check(!LayerOrderMath.MoveDown(x,low));for(var i=0;i<x.Count;i++)Check(x[i].ZIndex==i);Console.WriteLine("v30 layer: persistence");var d=Path.Combine(Path.GetTempPath(),"DeskCanvasLayer",Guid.NewGuid().ToString("N"));Directory.CreateDirectory(d);try{var r=new LayoutRepository(d);r.Save(new CanvasLayout{Items=[new CanvasItem{DisplayName="a",ZIndex=8},new CanvasItem{DisplayName="b",ZIndex=8}]});var y=r.Load().Items;Check(y.Count==2&&y[0].DisplayName=="a"&&y[0].ZIndex==0&&y[1].ZIndex==1);}finally{Directory.Delete(d,true);}Console.WriteLine("PASS v3.0 system responsive layout and layer ordering");}private static void Check(bool b){if(!b)throw new InvalidOperationException("v30 system/layer contract");}}
